SET XACT_ABORT ON;\nBEGIN TRANSACTION;\n\nIF OBJECT_ID('dbo.Prompt', 'U') IS NULL AND OBJECT_ID('dbo.Word', 'U') IS NOT NULL\n    EXEC sp_rename 'dbo.Word', 'Prompt';\n\nIF OBJECT_ID('dbo.Prompt', 'U') IS NULL\n    THROW 50001, 'Prompt catalog table is missing.', 1;\n\nIF EXISTS (SELECT 1 FROM dbo.Prompt WHERE Text IS NULL OR Language IS NULL)\n    THROW 50002, 'Resolve prompts with missing text or language before migration 005.', 1;\nIF EXISTS (SELECT Text, Language FROM dbo.Prompt GROUP BY Text, Language HAVING COUNT(*) > 1)\n    THROW 50003, 'Resolve duplicate prompt/language pairs before migration 005.', 1;\n\nIF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('dbo.Prompt') AND is_primary_key = 1)\nBEGIN\n    ALTER TABLE dbo.Prompt ALTER COLUMN Text NVARCHAR(255) NOT NULL;\n    ALTER TABLE dbo.Prompt ALTER COLUMN Language NVARCHAR(50) NOT NULL;\n    ALTER TABLE dbo.Prompt ADD CONSTRAINT PK_Prompt PRIMARY KEY (Text, Language);\nEND;\n\nCOMMIT;\n
